1	package yaml
2	
3	import (
4		"bytes"
5		"context"
6		"encoding"
7		"encoding/base64"
8		"fmt"
9		"io"
10		"math"
11		"os"
12		"path/filepath"
13		"reflect"
14		"sort"
15		"strconv"
16		"time"
17	
18		"golang.org/x/xerrors"
19	
20		"github.com/goccy/go-yaml/ast"
21		"github.com/goccy/go-yaml/internal/errors"
22		"github.com/goccy/go-yaml/parser"
23		"github.com/goccy/go-yaml/token"
24	)
25	
26	// Decoder reads and decodes YAML values from an input stream.
27	type Decoder struct {
28		reader               io.Reader
29		referenceReaders     []io.Reader
30		anchorNodeMap        map[string]ast.Node
31		anchorValueMap       map[string]reflect.Value
32		customUnmarshalerMap map[reflect.Type]func(interface{}, []byte) error
33		toCommentMap         CommentMap
34		opts                 []DecodeOption
35		referenceFiles       []string
36		referenceDirs        []string
37		isRecursiveDir       bool
38		isResolvedReference  bool
39		validator            StructValidator
40		disallowUnknownField bool
41		disallowDuplicateKey bool
42		useOrderedMap        bool
43		useJSONUnmarshaler   bool
44		parsedFile           *ast.File
45		streamIndex          int
46	}
47	
48	// NewDecoder returns a new decoder that reads from r.
49	func NewDecoder(r io.Reader, opts ...DecodeOption) *Decoder {
50		return &Decoder{
51			reader:               r,
52			anchorNodeMap:        map[string]ast.Node{},
53			anchorValueMap:       map[string]reflect.Value{},
54			customUnmarshalerMap: map[reflect.Type]func(interface{}, []byte) error{},
55			opts:                 opts,
56			referenceReaders:     []io.Reader{},
57			referenceFiles:       []string{},
58			referenceDirs:        []string{},
59			isRecursiveDir:       false,
60			isResolvedReference:  false,
61			disallowUnknownField: false,
62			disallowDuplicateKey: false,
63			useOrderedMap:        false,
64		}
65	}
66	
67	func (d *Decoder) castToFloat(v interface{}) interface{} {
68		switch vv := v.(type) {
69		case int:
70			return float64(vv)
71		case int8:
72			return float64(vv)
73		case int16:
74			return float64(vv)
75		case int32:
76			return float64(vv)
77		case int64:
78			return float64(vv)
79		case uint:
80			return float64(vv)
81		case uint8:
82			return float64(vv)
83		case uint16:
84			return float64(vv)
85		case uint32:
86			return float64(vv)
87		case uint64:
88			return float64(vv)
89		case float32:
90			return float64(vv)
91		case float64:
92			return vv
93		case string:
94			// if error occurred, return zero value
95			f, _ := strconv.ParseFloat(vv, 64)
96			return f
97		}
98		return 0
99	}
100	
101	func (d *Decoder) mergeValueNode(value ast.Node) ast.Node {
102		if value.Type() == ast.AliasType {
103			aliasNode := value.(*ast.AliasNode)
104			aliasName := aliasNode.Value.GetToken().Value
105			return d.anchorNodeMap[aliasName]
106		}
107		return value
108	}
109	
110	func (d *Decoder) mapKeyNodeToString(node ast.MapKeyNode) string {
111		key := d.nodeToValue(node)
112		if key == nil {
113			return "null"
114		}
115		if k, ok := key.(string); ok {
116			return k
117		}
118		return fmt.Sprint(key)
119	}
120	
121	func (d *Decoder) setToMapValue(node ast.Node, m map[string]interface{}) {
122		d.setPathToCommentMap(node)
123		switch n := node.(type) {
124		case *ast.MappingValueNode:
125			if n.Key.Type() == ast.MergeKeyType {
126				d.setToMapValue(d.mergeValueNode(n.Value), m)
127			} else {
128				key := d.mapKeyNodeToString(n.Key)
129				m[key] = d.nodeToValue(n.Value)
130			}
131		case *ast.MappingNode:
132			for _, value := range n.Values {
133				d.setToMapValue(value, m)
134			}
135		case *ast.AnchorNode:
136			anchorName := n.Name.GetToken().Value
137			d.anchorNodeMap[anchorName] = n.Value
138		}
139	}
140	
141	func (d *Decoder) setToOrderedMapValue(node ast.Node, m *MapSlice) {
142		switch n := node.(type) {
143		case *ast.MappingValueNode:
144			if n.Key.Type() == ast.MergeKeyType {
145				d.setToOrderedMapValue(d.mergeValueNode(n.Value), m)
146			} else {
147				key := d.mapKeyNodeToString(n.Key)
148				*m = append(*m, MapItem{Key: key, Value: d.nodeToValue(n.Value)})
149			}
150		case *ast.MappingNode:
151			for _, value := range n.Values {
152				d.setToOrderedMapValue(value, m)
153			}
154		}
155	}
156	
157	func (d *Decoder) setPathToCommentMap(node ast.Node) {
158		if d.toCommentMap == nil {
159			return
160		}
161		d.addHeadOrLineCommentToMap(node)
162		d.addFootCommentToMap(node)
163	}
164	
165	func (d *Decoder) addHeadOrLineCommentToMap(node ast.Node) {
166		sequence, ok := node.(*ast.SequenceNode)
167		if ok {
168			d.addSequenceNodeCommentToMap(sequence)
169			return
170		}
171		commentGroup := node.GetComment()
172		if commentGroup == nil {
173			return
174		}
175		texts := []string{}
176		targetLine := node.GetToken().Position.Line
177		minCommentLine := math.MaxInt
178		for _, comment := range commentGroup.Comments {
179			if minCommentLine > comment.Token.Position.Line {
180				minCommentLine = comment.Token.Position.Line
181			}
182			texts = append(texts, comment.Token.Value)
183		}
184		if len(texts) == 0 {
185			return
186		}
187		commentPath := node.GetPath()
188		if minCommentLine < targetLine {
189			d.addCommentToMap(commentPath, HeadComment(texts...))
190		} else {
191			d.addCommentToMap(commentPath, LineComment(texts[0]))
192		}
193	}
194	
195	func (d *Decoder) addSequenceNodeCommentToMap(node *ast.SequenceNode) {
196		if len(node.ValueHeadComments) != 0 {
197			for idx, headComment := range node.ValueHeadComments {
198				if headComment == nil {
199					continue
200				}
201				texts := make([]string, 0, len(headComment.Comments))
202				for _, comment := range headComment.Comments {
203					texts = append(texts, comment.Token.Value)
204				}
205				if len(texts) != 0 {
206					d.addCommentToMap(node.Values[idx].GetPath(), HeadComment(texts...))
207				}
208			}
209		}
210		firstElemHeadComment := node.GetComment()
211		if firstElemHeadComment != nil {
212			texts := make([]string, 0, len(firstElemHeadComment.Comments))
213			for _, comment := range firstElemHeadComment.Comments {
214				texts = append(texts, comment.Token.Value)
215			}
216			if len(texts) != 0 {
217				d.addCommentToMap(node.Values[0].GetPath(), HeadComment(texts...))
218			}
219		}
220	}
221	
222	func (d *Decoder) addFootCommentToMap(node ast.Node) {
223		var (
224			footComment     *ast.CommentGroupNode
225			footCommentPath string = node.GetPath()
226		)
227		switch n := node.(type) {
228		case *ast.SequenceNode:
229			if len(n.Values) != 0 {
230				footCommentPath = n.Values[len(n.Values)-1].GetPath()
231			}
232			footComment = n.FootComment
233		case *ast.MappingNode:
234			footComment = n.FootComment
235		case *ast.MappingValueNode:
236			footComment = n.FootComment
237		}
238		if footComment == nil {
239			return
240		}
241		var texts []string
242		for _, comment := range footComment.Comments {
243			texts = append(texts, comment.Token.Value)
244		}
245		if len(texts) != 0 {
246			d.addCommentToMap(footCommentPath, FootComment(texts...))
247		}
248	}
249	
250	func (d *Decoder) addCommentToMap(path string, comment *Comment) {
251		for _, c := range d.toCommentMap[path] {
252			if c.Position == comment.Position {
253				// already added same comment
254				return
255			}
256		}
257		d.toCommentMap[path] = append(d.toCommentMap[path], comment)
258		sort.Slice(d.toCommentMap[path], func(i, j int) bool {
259			return d.toCommentMap[path][i].Position < d.toCommentMap[path][j].Position
260		})
261	}
262	
263	func (d *Decoder) nodeToValue(node ast.Node) interface{} {
264		d.setPathToCommentMap(node)
265		switch n := node.(type) {
266		case *ast.NullNode:
267			return nil
268		case *ast.StringNode:
269			return n.GetValue()
270		case *ast.IntegerNode:
271			return n.GetValue()
272		case *ast.FloatNode:
273			return n.GetValue()
274		case *ast.BoolNode:
275			return n.GetValue()
276		case *ast.InfinityNode:
277			return n.GetValue()
278		case *ast.NanNode:
279			return n.GetValue()
280		case *ast.TagNode:
281			switch token.ReservedTagKeyword(n.Start.Value) {
282			case token.TimestampTag:
283				t, _ := d.castToTime(n.Value)
284				return t
285			case token.IntegerTag:
286				i, _ := strconv.Atoi(fmt.Sprint(d.nodeToValue(n.Value)))
287				return i
288			case token.FloatTag:
289				return d.castToFloat(d.nodeToValue(n.Value))
290			case token.NullTag:
291				return nil
292			case token.BinaryTag:
293				b, _ := base64.StdEncoding.DecodeString(d.nodeToValue(n.Value).(string))
294				return b
295			case token.StringTag:
296				return d.nodeToValue(n.Value)
297			case token.MappingTag:
298				return d.nodeToValue(n.Value)
299			}
300		case *ast.AnchorNode:
301			anchorName := n.Name.GetToken().Value
302			anchorValue := d.nodeToValue(n.Value)
303			d.anchorNodeMap[anchorName] = n.Value
304			return anchorValue
305		case *ast.AliasNode:
306			aliasName := n.Value.GetToken().Value
307			node := d.anchorNodeMap[aliasName]
308			return d.nodeToValue(node)
309		case *ast.LiteralNode:
310			return n.Value.GetValue()
311		case *ast.MappingKeyNode:
312			return d.nodeToValue(n.Value)
313		case *ast.MappingValueNode:
314			if n.Key.Type() == ast.MergeKeyType {
315				value := d.mergeValueNode(n.Value)
316				if d.useOrderedMap {
317					m := MapSlice{}
318					d.setToOrderedMapValue(value, &m)
319					return m
320				}
321				m := map[string]interface{}{}
322				d.setToMapValue(value, m)
323				return m
324			}
325			key := d.mapKeyNodeToString(n.Key)
326			if d.useOrderedMap {
327				return MapSlice{{Key: key, Value: d.nodeToValue(n.Value)}}
328			}
329			return map[string]interface{}{
330				key: d.nodeToValue(n.Value),
331			}
332		case *ast.MappingNode:
333			if d.useOrderedMap {
334				m := make(MapSlice, 0, len(n.Values))
335				for _, value := range n.Values {
336					d.setToOrderedMapValue(value, &m)
337				}
338				return m
339			}
340			m := make(map[string]interface{}, len(n.Values))
341			for _, value := range n.Values {
342				d.setToMapValue(value, m)
343			}
344			return m
345		case *ast.SequenceNode:
346			v := make([]interface{}, 0, len(n.Values))
347			for _, value := range n.Values {
348				v = append(v, d.nodeToValue(value))
349			}
350			return v
351		}
352		return nil
353	}
354	
355	func (d *Decoder) resolveAlias(node ast.Node) (ast.Node, error) {
356		switch n := node.(type) {
357		case *ast.MappingNode:
358			for idx, v := range n.Values {
359				value, err := d.resolveAlias(v)
360				if err != nil {
361					return nil, err
362				}
363				n.Values[idx] = value.(*ast.MappingValueNode)
364			}
365		case *ast.TagNode:
366			value, err := d.resolveAlias(n.Value)
367			if err != nil {
368				return nil, err
369			}
370			n.Value = value
371		case *ast.MappingKeyNode:
372			value, err := d.resolveAlias(n.Value)
373			if err != nil {
374				return nil, err
375			}
376			n.Value = value
377		case *ast.MappingValueNode:
378			if n.Key.Type() == ast.MergeKeyType && n.Value.Type() == ast.AliasType {
379				value, err := d.resolveAlias(n.Value)
380				if err != nil {
381					return nil, err
382				}
383				keyColumn := n.Key.GetToken().Position.Column
384				requiredColumn := keyColumn + 2
385				value.AddColumn(requiredColumn)
386				n.Value = value
387			} else {
388				key, err := d.resolveAlias(n.Key)
389				if err != nil {
390					return nil, err
391				}
392				n.Key = key.(ast.MapKeyNode)
393				value, err := d.resolveAlias(n.Value)
394				if err != nil {
395					return nil, err
396				}
397				n.Value = value
398			}
399		case *ast.SequenceNode:
400			for idx, v := range n.Values {
401				value, err := d.resolveAlias(v)
402				if err != nil {
403					return nil, err
404				}
405				n.Values[idx] = value
406			}
407		case *ast.AliasNode:
408			aliasName := n.Value.GetToken().Value
409			node := d.anchorNodeMap[aliasName]
410			if node == nil {
411				return nil, xerrors.Errorf("cannot find anchor by alias name %s", aliasName)
412			}
413			return d.resolveAlias(node)
414		}
415		return node, nil
416	}
417	
418	func (d *Decoder) getMapNode(node ast.Node) (ast.MapNode, error) {
419		if _, ok := node.(*ast.NullNode); ok {
420			return nil, nil
421		}
422		if anchor, ok := node.(*ast.AnchorNode); ok {
423			mapNode, ok := anchor.Value.(ast.MapNode)
424			if ok {
425				return mapNode, nil
426			}
427			return nil, errUnexpectedNodeType(anchor.Value.Type(), ast.MappingType, node.GetToken())
428		}
429		if alias, ok := node.(*ast.AliasNode); ok {
430			aliasName := alias.Value.GetToken().Value
431			node := d.anchorNodeMap[aliasName]
432			if node == nil {
433				return nil, xerrors.Errorf("cannot find anchor by alias name %s", aliasName)
434			}
435			mapNode, ok := node.(ast.MapNode)
436			if ok {
437				return mapNode, nil
438			}
439			return nil, errUnexpectedNodeType(node.Type(), ast.MappingType, node.GetToken())
440		}
441		mapNode, ok := node.(ast.MapNode)
442		if !ok {
443			return nil, errUnexpectedNodeType(node.Type(), ast.MappingType, node.GetToken())
444		}
445		return mapNode, nil
446	}
447	
448	func (d *Decoder) getArrayNode(node ast.Node) (ast.ArrayNode, error) {
449		if _, ok := node.(*ast.NullNode); ok {
450			return nil, nil
451		}
452		if anchor, ok := node.(*ast.AnchorNode); ok {
453			arrayNode, ok := anchor.Value.(ast.ArrayNode)
454			if ok {
455				return arrayNode, nil
456			}
457	
458			return nil, errUnexpectedNodeType(anchor.Value.Type(), ast.SequenceType, node.GetToken())
459		}
460		if alias, ok := node.(*ast.AliasNode); ok {
461			aliasName := alias.Value.GetToken().Value
462			node := d.anchorNodeMap[aliasName]
463			if node == nil {
464				return nil, xerrors.Errorf("cannot find anchor by alias name %s", aliasName)
465			}
466			arrayNode, ok := node.(ast.ArrayNode)
467			if ok {
468				return arrayNode, nil
469			}
470			return nil, errUnexpectedNodeType(node.Type(), ast.SequenceType, node.GetToken())
471		}
472		arrayNode, ok := node.(ast.ArrayNode)
473		if !ok {
474			return nil, errUnexpectedNodeType(node.Type(), ast.SequenceType, node.GetToken())
475		}
476		return arrayNode, nil
477	}
478	
479	func (d *Decoder) fileToNode(f *ast.File) ast.Node {
480		for _, doc := range f.Docs {
481			if v := d.nodeToValue(doc.Body); v != nil {
482				return doc.Body
483			}
484		}
485		return nil
486	}
487	
488	func (d *Decoder) convertValue(v reflect.Value, typ reflect.Type, src ast.Node) (reflect.Value, error) {
489		if typ.Kind() != reflect.String {
490			if !v.Type().ConvertibleTo(typ) {
491	
492				// Special case for "strings -> floats" aka scientific notation
493				// If the destination type is a float and the source type is a string, check if we can
494				// use strconv.ParseFloat to convert the string to a float.
495				if (typ.Kind() == reflect.Float32 || typ.Kind() == reflect.Float64) &&
496					v.Type().Kind() == reflect.String {
497					if f, err := strconv.ParseFloat(v.String(), 64); err == nil {
498						if typ.Kind() == reflect.Float32 {
499							return reflect.ValueOf(float32(f)), nil
500						} else if typ.Kind() == reflect.Float64 {
501							return reflect.ValueOf(f), nil
502						}
503						// else, fall through to the error below
504					}
505				}
506				return reflect.Zero(typ), errTypeMismatch(typ, v.Type(), src.GetToken())
507			}
508			return v.Convert(typ), nil
509		}
510		// cast value to string
511		switch v.Type().Kind() {
512		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
513			return reflect.ValueOf(fmt.Sprint(v.Int())), nil
514		case reflect.Float32, reflect.Float64:
515			return reflect.ValueOf(fmt.Sprint(v.Float())), nil
516		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
517			return reflect.ValueOf(fmt.Sprint(v.Uint())), nil
518		case reflect.Bool:
519			return reflect.ValueOf(fmt.Sprint(v.Bool())), nil
520		}
521		if !v.Type().ConvertibleTo(typ) {
522			return reflect.Zero(typ), errTypeMismatch(typ, v.Type(), src.GetToken())
523		}
524		return v.Convert(typ), nil
525	}
