572	func (d *Decoder) deleteStructKeys(structType reflect.Type, unknownFields map[string]ast.Node) error {
573		if structType.Kind() == reflect.Ptr {
574			structType = structType.Elem()
575		}
576		structFieldMap, err := structFieldMap(structType)
577		if err != nil {
578			return errors.Wrapf(err, "failed to create struct field map")
579		}
580	
581		for j := 0; j < structType.NumField(); j++ {
582			field := structType.Field(j)
583			if isIgnoredStructField(field) {
584				continue
585			}
586	
587			structField, exists := structFieldMap[field.Name]
588			if !exists {
589				continue
590			}
