711	func (d *Decoder) decodeByUnmarshaler(ctx context.Context, dst reflect.Value, src ast.Node) error {
712		ptrValue := dst.Addr()
713		if unmarshaler, exists := d.unmarshalerFromCustomUnmarshalerMap(ptrValue.Type()); exists {
714			b, err := d.unmarshalableDocument(src)
715			if err != nil {
716				return errors.Wrapf(err, "failed to UnmarshalYAML")
717			}
718			if err := unmarshaler(ptrValue.Interface(), b); err != nil {
719				return errors.Wrapf(err, "failed to UnmarshalYAML")
720			}
721			return nil
722		}
723		iface := ptrValue.Interface()
724	
725		if unmarshaler, ok := iface.(BytesUnmarshalerContext); ok {
726			b, err := d.unmarshalableDocument(src)
727			if err != nil {
728				return errors.Wrapf(err, "failed to UnmarshalYAML")
729			}
730			if err := unmarshaler.UnmarshalYAML(ctx, b); err != nil {
731				return errors.Wrapf(err, "failed to UnmarshalYAML")
732			}
733			return nil
734		}
735	
736		if unmarshaler, ok := iface.(BytesUnmarshaler); ok {
737			b, err := d.unmarshalableDocument(src)
738			if err != nil {
739				return errors.Wrapf(err, "failed to UnmarshalYAML")
740			}
741			if err := unmarshaler.UnmarshalYAML(b); err != nil {
742				return errors.Wrapf(err, "failed to UnmarshalYAML")
743			}
744			return nil
745		}
746	
747		if unmarshaler, ok := iface.(InterfaceUnmarshalerContext); ok {
748			if err := unmarshaler.UnmarshalYAML(ctx, func(v interface{}) error {
749				rv := reflect.ValueOf(v)
750				if rv.Type().Kind() != reflect.Ptr {
751					return errors.ErrDecodeRequiredPointerType
752				}
753				if err := d.decodeValue(ctx, rv.Elem(), src); err != nil {
754					return errors.Wrapf(err, "failed to decode value")
755				}
756				return nil
757			}); err != nil {
758				return errors.Wrapf(err, "failed to UnmarshalYAML")
759			}
760			return nil
761		}
762	
763		if unmarshaler, ok := iface.(InterfaceUnmarshaler); ok {
764			if err := unmarshaler.UnmarshalYAML(func(v interface{}) error {
765				rv := reflect.ValueOf(v)
766				if rv.Type().Kind() != reflect.Ptr {
767					return errors.ErrDecodeRequiredPointerType
768				}
769				if err := d.decodeValue(ctx, rv.Elem(), src); err != nil {
770					return errors.Wrapf(err, "failed to decode value")
771				}
772				return nil
773			}); err != nil {
774				return errors.Wrapf(err, "failed to UnmarshalYAML")
775			}
776			return nil
777		}
778	
779		if _, ok := iface.(*time.Time); ok {
780			return d.decodeTime(ctx, dst, src)
781		}
782	
783		if _, ok := iface.(*time.Duration); ok {
784			return d.decodeDuration(ctx, dst, src)
785		}
786	
787		if unmarshaler, isText := iface.(encoding.TextUnmarshaler); isText {
788			b, ok, err := d.unmarshalableText(src)
789			if err != nil {
790				return errors.Wrapf(err, "failed to UnmarshalText")
791			}
792			if ok {
793				if err := unmarshaler.UnmarshalText(b); err != nil {
794					return errors.Wrapf(err, "failed to UnmarshalText")
795				}
796				return nil
797			}
798		}
799	
800		if d.useJSONUnmarshaler {
801			if unmarshaler, ok := iface.(jsonUnmarshaler); ok {
802				b, err := d.unmarshalableDocument(src)
803				if err != nil {
804					return errors.Wrapf(err, "failed to UnmarshalJSON")
805				}
806				jsonBytes, err := YAMLToJSON(b)
807				if err != nil {
808					return errors.Wrapf(err, "failed to convert yaml to json")
809				}
810				jsonBytes = bytes.TrimRight(jsonBytes, "\n")
811				if err := unmarshaler.UnmarshalJSON(jsonBytes); err != nil {
812					return errors.Wrapf(err, "failed to UnmarshalJSON")
813				}
814				return nil
815			}
816		}
817	
818		return xerrors.Errorf("does not implemented Unmarshaler")
819	}
