825	func (d *Decoder) decodeValue(ctx context.Context, dst reflect.Value, src ast.Node) error {
826		if src.Type() == ast.AnchorType {
827			anchorName := src.(*ast.AnchorNode).Name.GetToken().Value
828			if _, exists := d.anchorValueMap[anchorName]; !exists {
829				d.anchorValueMap[anchorName] = dst
830			}
831		}
832		if d.canDecodeByUnmarshaler(dst) {
833			if err := d.decodeByUnmarshaler(ctx, dst, src); err != nil {
834				return errors.Wrapf(err, "failed to decode by unmarshaler")
835			}
836			return nil
837		}
838		valueType := dst.Type()
839		switch valueType.Kind() {
840		case reflect.Ptr:
841			if dst.IsNil() {
842				return nil
843			}
844			if src.Type() == ast.NullType {
845				// set nil value to pointer
846				dst.Set(reflect.Zero(valueType))
847				return nil
848			}
849			v := d.createDecodableValue(dst.Type())
850			if err := d.decodeValue(ctx, v, src); err != nil {
851				return errors.Wrapf(err, "failed to decode ptr value")
852			}
853			dst.Set(d.castToAssignableValue(v, dst.Type()))
854		case reflect.Interface:
855			if dst.Type() == astNodeType {
856				dst.Set(reflect.ValueOf(src))
857				return nil
858			}
859			v := reflect.ValueOf(d.nodeToValue(src))
860			if v.IsValid() {
861				dst.Set(v)
862			}
863		case reflect.Map:
864			return d.decodeMap(ctx, dst, src)
865		case reflect.Array:
866			return d.decodeArray(ctx, dst, src)
867		case reflect.Slice:
868			if mapSlice, ok := dst.Addr().Interface().(*MapSlice); ok {
869				return d.decodeMapSlice(ctx, mapSlice, src)
870			}
871			return d.decodeSlice(ctx, dst, src)
872		case reflect.Struct:
873			if mapItem, ok := dst.Addr().Interface().(*MapItem); ok {
874				return d.decodeMapItem(ctx, mapItem, src)
875			}
876			return d.decodeStruct(ctx, dst, src)
877		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
878			v := d.nodeToValue(src)
879			switch vv := v.(type) {
880			case int64:
881				if !dst.OverflowInt(vv) {
882					dst.SetInt(vv)
883					return nil
884				}
885			case uint64:
886				if vv <= math.MaxInt64 && !dst.OverflowInt(int64(vv)) {
887					dst.SetInt(int64(vv))
888					return nil
889				}
890			case float64:
891				if vv <= math.MaxInt64 && !dst.OverflowInt(int64(vv)) {
892					dst.SetInt(int64(vv))
893					return nil
894				}
895			case string: // handle scientific notation
896				if i, err := strconv.ParseFloat(vv, 64); err == nil {
897					if 0 <= i && i <= math.MaxUint64 && !dst.OverflowInt(int64(i)) {
898						dst.SetInt(int64(i))
899						return nil
900					}
901				} else { // couldn't be parsed as float
902					return errTypeMismatch(valueType, reflect.TypeOf(v), src.GetToken())
903				}
904			default:
905				return errTypeMismatch(valueType, reflect.TypeOf(v), src.GetToken())
906			}
907			return errOverflow(valueType, fmt.Sprint(v))
908		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
909			v := d.nodeToValue(src)
910			switch vv := v.(type) {
911			case int64:
912				if 0 <= vv && !dst.OverflowUint(uint64(vv)) {
913					dst.SetUint(uint64(vv))
914					return nil
915				}
916			case uint64:
917				if !dst.OverflowUint(vv) {
918					dst.SetUint(vv)
919					return nil
920				}
921			case float64:
922				if 0 <= vv && vv <= math.MaxUint64 && !dst.OverflowUint(uint64(vv)) {
923					dst.SetUint(uint64(vv))
924					return nil
925				}
926			case string: // handle scientific notation
927				if i, err := strconv.ParseFloat(vv, 64); err == nil {
928					if 0 <= i && i <= math.MaxUint64 && !dst.OverflowUint(uint64(i)) {
929						dst.SetUint(uint64(i))
930						return nil
931					}
932				} else { // couldn't be parsed as float
933					return errTypeMismatch(valueType, reflect.TypeOf(v), src.GetToken())
934				}
935	
936			default:
937				return errTypeMismatch(valueType, reflect.TypeOf(v), src.GetToken())
938			}
939			return errOverflow(valueType, fmt.Sprint(v))
940		}
941		v := reflect.ValueOf(d.nodeToValue(src))
942		if v.IsValid() {
943			convertedValue, err := d.convertValue(v, dst.Type(), src)
944			if err != nil {
945				return errors.Wrapf(err, "failed to convert value")
946			}
947			dst.Set(convertedValue)
948		}
949		return nil
950	}
