952	func (d *Decoder) createDecodableValue(typ reflect.Type) reflect.Value {
953		for {
954			if typ.Kind() == reflect.Ptr {
955				typ = typ.Elem()
956				continue
957			}
958			break
959		}
960		return reflect.New(typ).Elem()
961	}
