963	func (d *Decoder) castToAssignableValue(value reflect.Value, target reflect.Type) reflect.Value {
964		if target.Kind() != reflect.Ptr {
965			return value
966		}
967		maxTryCount := 5
968		tryCount := 0
969		for {
970			if tryCount > maxTryCount {
971				return value
972			}
973			if value.Type().AssignableTo(target) {
974				break
975			}
976			value = value.Addr()
977			tryCount++
978		}
979		return value
980	}
