1008	func (d *Decoder) keyToNodeMap(node ast.Node, ignoreMergeKey bool, getKeyOrValueNode func(*ast.MapNodeIter) ast.Node) (map[string]ast.Node, error) {
1009		mapNode, err := d.getMapNode(node)
1010		if err != nil {
1011			return nil, errors.Wrapf(err, "failed to get map node")
1012		}
1013		keyMap := map[string]struct{}{}
1014		keyToNodeMap := map[string]ast.Node{}
1015		if mapNode == nil {
1016			return keyToNodeMap, nil
1017		}
1018		mapIter := mapNode.MapRange()
1019		for mapIter.Next() {
1020			keyNode := mapIter.Key()
1021			if keyNode.Type() == ast.MergeKeyType {
1022				if ignoreMergeKey {
1023					continue
1024				}
1025				mergeMap, err := d.keyToNodeMap(mapIter.Value(), ignoreMergeKey, getKeyOrValueNode)
1026				if err != nil {
1027					return nil, errors.Wrapf(err, "failed to get keyToNodeMap by MergeKey node")
1028				}
1029				for k, v := range mergeMap {
1030					if err := d.validateDuplicateKey(keyMap, k, v); err != nil {
1031						return nil, errors.Wrapf(err, "invalid struct key")
1032					}
1033					keyToNodeMap[k] = v
1034				}
1035			} else {
1036				key, ok := d.nodeToValue(keyNode).(string)
1037				if !ok {
1038					return nil, errors.Wrapf(err, "failed to decode map key")
1039				}
1040				if err := d.validateDuplicateKey(keyMap, key, keyNode); err != nil {
1041					return nil, errors.Wrapf(err, "invalid struct key")
1042				}
1043				keyToNodeMap[key] = getKeyOrValueNode(mapIter)
1044			}
1045		}
1046		return keyToNodeMap, nil
1047	}
