1065	func (d *Decoder) setDefaultValueIfConflicted(v reflect.Value, fieldMap StructFieldMap) error {
1066		typ := v.Type()
1067		if typ.Kind() != reflect.Struct {
1068			return nil
1069		}
1070		embeddedStructFieldMap, err := structFieldMap(typ)
1071		if err != nil {
1072			return errors.Wrapf(err, "failed to get struct field map by embedded type")
1073		}
1074		for i := 0; i < typ.NumField(); i++ {
1075			field := typ.Field(i)
1076			if isIgnoredStructField(field) {
1077				continue
1078			}
1079			structField := embeddedStructFieldMap[field.Name]
1080			if !fieldMap.isIncludedRenderName(structField.RenderName) {
1081				continue
1082			}
1083			// if declared same key name, set default value
1084			fieldValue := v.Field(i)
1085			if fieldValue.CanSet() {
1086				fieldValue.Set(reflect.Zero(fieldValue.Type()))
1087			}
1088		}
1089		return nil
1090	}
