1092	// This is a subset of the formats allowed by the regular expression
1093	// defined at http://yaml.org/type/timestamp.html.
1094	var allowedTimestampFormats = []string{
1095		"2006-1-2T15:4:5.999999999Z07:00", // RCF3339Nano with short date fields.
1096		"2006-1-2t15:4:5.999999999Z07:00", // RFC3339Nano with short date fields and lower-case "t".
1097		"2006-1-2 15:4:5.999999999",       // space separated with no time zone
1098		"2006-1-2",                        // date only
