1101	func (d *Decoder) castToTime(src ast.Node) (time.Time, error) {
1102		if src == nil {
1103			return time.Time{}, nil
1104		}
1105		v := d.nodeToValue(src)
1106		if t, ok := v.(time.Time); ok {
1107			return t, nil
1108		}
1109		s, ok := v.(string)
1110		if !ok {
1111			return time.Time{}, errTypeMismatch(reflect.TypeOf(time.Time{}), reflect.TypeOf(v), src.GetToken())
1112		}
1113		for _, format := range allowedTimestampFormats {
1114			t, err := time.Parse(format, s)
1115			if err != nil {
1116				// invalid format
1117				continue
1118			}
1119			return t, nil
1120		}
1121		return time.Time{}, nil
1122	}
