1133	func (d *Decoder) castToDuration(src ast.Node) (time.Duration, error) {
1134		if src == nil {
1135			return 0, nil
1136		}
1137		v := d.nodeToValue(src)
1138		if t, ok := v.(time.Duration); ok {
1139			return t, nil
1140		}
1141		s, ok := v.(string)
1142		if !ok {
1143			return 0, errTypeMismatch(reflect.TypeOf(time.Duration(0)), reflect.TypeOf(v), src.GetToken())
1144		}
1145		t, err := time.ParseDuration(s)
1146		if err != nil {
1147			return 0, errors.Wrapf(err, "failed to parse duration")
1148		}
1149		return t, nil
1150	}
