1161	// getMergeAliasName support single alias only
1162	func (d *Decoder) getMergeAliasName(src ast.Node) string {
1163		mapNode, err := d.getMapNode(src)
1164		if err != nil {
1165			return ""
1166		}
1167		if mapNode == nil {
1168			return ""
1169		}
1170		mapIter := mapNode.MapRange()
1171		for mapIter.Next() {
1172			key := mapIter.Key()
1173			value := mapIter.Value()
1174			if key.Type() == ast.MergeKeyType && value.Type() == ast.AliasType {
1175				return value.(*ast.AliasNode).Value.GetToken().Value
1176			}
1177		}
1178		return ""
1179	}
