1181	func (d *Decoder) decodeStruct(ctx context.Context, dst reflect.Value, src ast.Node) error {
1182		if src == nil {
1183			return nil
1184		}
1185		structType := dst.Type()
1186		srcValue := reflect.ValueOf(src)
1187		srcType := srcValue.Type()
1188		if srcType.Kind() == reflect.Ptr {
1189			srcType = srcType.Elem()
1190			srcValue = srcValue.Elem()
1191		}
1192		if structType == srcType {
1193			// dst value implements ast.Node
1194			dst.Set(srcValue)
1195			return nil
1196		}
1197		structFieldMap, err := structFieldMap(structType)
1198		if err != nil {
1199			return errors.Wrapf(err, "failed to create struct field map")
1200		}
1201		ignoreMergeKey := structFieldMap.hasMergeProperty()
1202		keyToNodeMap, err := d.keyToValueNodeMap(src, ignoreMergeKey)
1203		if err != nil {
1204			return errors.Wrapf(err, "failed to get keyToValueNodeMap")
1205		}
1206		var unknownFields map[string]ast.Node
1207		if d.disallowUnknownField {
1208			unknownFields, err = d.keyToKeyNodeMap(src, ignoreMergeKey)
1209			if err != nil {
1210				return errors.Wrapf(err, "failed to get keyToKeyNodeMap")
1211			}
1212		}
1213	
1214		aliasName := d.getMergeAliasName(src)
1215		var foundErr error
1216	
1217		for i := 0; i < structType.NumField(); i++ {
1218			field := structType.Field(i)
1219			if isIgnoredStructField(field) {
1220				continue
1221			}
1222			structField := structFieldMap[field.Name]
1223			if structField.IsInline {
1224				fieldValue := dst.FieldByName(field.Name)
1225				if structField.IsAutoAlias {
1226					if aliasName != "" {
1227						newFieldValue := d.anchorValueMap[aliasName]
1228						if newFieldValue.IsValid() {
1229							fieldValue.Set(d.castToAssignableValue(newFieldValue, fieldValue.Type()))
1230						}
1231					}
1232					continue
1233				}
1234				if !fieldValue.CanSet() {
1235					return xerrors.Errorf("cannot set embedded type as unexported field %s.%s", field.PkgPath, field.Name)
1236				}
1237				if fieldValue.Type().Kind() == reflect.Ptr && src.Type() == ast.NullType {
1238					// set nil value to pointer
1239					fieldValue.Set(reflect.Zero(fieldValue.Type()))
1240					continue
1241				}
1242				mapNode := ast.Mapping(nil, false)
1243				for k, v := range keyToNodeMap {
1244					key := &ast.StringNode{BaseNode: &ast.BaseNode{}, Value: k}
1245					mapNode.Values = append(mapNode.Values, ast.MappingValue(nil, key, v))
1246				}
1247				newFieldValue, err := d.createDecodedNewValue(ctx, fieldValue.Type(), fieldValue, mapNode)
1248				if d.disallowUnknownField {
1249					if err := d.deleteStructKeys(fieldValue.Type(), unknownFields); err != nil {
1250						return errors.Wrapf(err, "cannot delete struct keys")
1251					}
1252				}
1253	
1254				if err != nil {
1255					if foundErr != nil {
1256						continue
1257					}
1258					var te *errors.TypeError
1259					if xerrors.As(err, &te) {
1260						if te.StructFieldName != nil {
1261							fieldName := fmt.Sprintf("%s.%s", structType.Name(), *te.StructFieldName)
1262							te.StructFieldName = &fieldName
1263						} else {
1264							fieldName := fmt.Sprintf("%s.%s", structType.Name(), field.Name)
1265							te.StructFieldName = &fieldName
1266						}
1267						foundErr = te
1268						continue
1269					} else {
1270						foundErr = err
1271					}
1272					continue
1273				}
1274				d.setDefaultValueIfConflicted(newFieldValue, structFieldMap)
1275				fieldValue.Set(d.castToAssignableValue(newFieldValue, fieldValue.Type()))
1276				continue
1277			}
1278			v, exists := keyToNodeMap[structField.RenderName]
1279			if !exists {
1280				continue
1281			}
1282			delete(unknownFields, structField.RenderName)
1283			fieldValue := dst.FieldByName(field.Name)
1284			if fieldValue.Type().Kind() == reflect.Ptr && src.Type() == ast.NullType {
1285				// set nil value to pointer
1286				fieldValue.Set(reflect.Zero(fieldValue.Type()))
1287				continue
1288			}
1289			newFieldValue, err := d.createDecodedNewValue(ctx, fieldValue.Type(), fieldValue, v)
1290			if err != nil {
1291				if foundErr != nil {
1292					continue
1293				}
1294				var te *errors.TypeError
1295				if xerrors.As(err, &te) {
1296					fieldName := fmt.Sprintf("%s.%s", structType.Name(), field.Name)
1297					te.StructFieldName = &fieldName
1298					foundErr = te
1299				} else {
1300					foundErr = err
1301				}
1302				continue
1303			}
1304			fieldValue.Set(d.castToAssignableValue(newFieldValue, fieldValue.Type()))
1305		}
1306		if foundErr != nil {
1307			return errors.Wrapf(foundErr, "failed to decode value")
1308		}
1309	
1310		// Ignore unknown fields when parsing an inline struct (recognized by a nil token).
1311		// Unknown fields are expected (they could be fields from the parent struct).
1312		if len(unknownFields) != 0 && d.disallowUnknownField && src.GetToken() != nil {
1313			for key, node := range unknownFields {
1314				return errUnknownField(fmt.Sprintf(`unknown field "%s"`, key), node.GetToken())
1315			}
1316		}
1317	
1318		if d.validator != nil {
1319			if err := d.validator.Struct(dst.Interface()); err != nil {
1320				ev := reflect.ValueOf(err)
1321				if ev.Type().Kind() == reflect.Slice {
1322					for i := 0; i < ev.Len(); i++ {
1323						fieldErr, ok := ev.Index(i).Interface().(FieldError)
1324						if !ok {
1325							continue
1326						}
1327						fieldName := fieldErr.StructField()
1328						structField, exists := structFieldMap[fieldName]
1329						if !exists {
1330							continue
1331						}
1332						node, exists := keyToNodeMap[structField.RenderName]
1333						if exists {
1334							// TODO: to make FieldError message cutomizable
1335							return errors.ErrSyntax(fmt.Sprintf("%s", err), node.GetToken())
1336						} else if t := src.GetToken(); t != nil && t.Prev != nil && t.Prev.Prev != nil {
1337							// A missing required field will not be in the keyToNodeMap
1338							// the error needs to be associated with the parent of the source node
1339							return errors.ErrSyntax(fmt.Sprintf("%s", err), t.Prev.Prev)
1340						}
1341					}
1342				}
1343				return err
1344			}
1345		}
1346		return nil
1347	}
