1349	func (d *Decoder) decodeArray(ctx context.Context, dst reflect.Value, src ast.Node) error {
1350		arrayNode, err := d.getArrayNode(src)
1351		if err != nil {
1352			return errors.Wrapf(err, "failed to get array node")
1353		}
1354		if arrayNode == nil {
1355			return nil
1356		}
1357		iter := arrayNode.ArrayRange()
1358		arrayValue := reflect.New(dst.Type()).Elem()
1359		arrayType := dst.Type()
1360		elemType := arrayType.Elem()
1361		idx := 0
1362	
1363		var foundErr error
1364		for iter.Next() {
1365			v := iter.Value()
1366			if elemType.Kind() == reflect.Ptr && v.Type() == ast.NullType {
1367				// set nil value to pointer
1368				arrayValue.Index(idx).Set(reflect.Zero(elemType))
1369			} else {
1370				dstValue, err := d.createDecodedNewValue(ctx, elemType, reflect.Value{}, v)
1371				if err != nil {
1372					if foundErr == nil {
1373						foundErr = err
1374					}
1375					continue
1376				} else {
1377					arrayValue.Index(idx).Set(d.castToAssignableValue(dstValue, elemType))
1378				}
1379			}
1380			idx++
1381		}
1382		dst.Set(arrayValue)
1383		if foundErr != nil {
1384			return errors.Wrapf(foundErr, "failed to decode value")
1385		}
1386		return nil
1387	}
