1389	func (d *Decoder) decodeSlice(ctx context.Context, dst reflect.Value, src ast.Node) error {
1390		arrayNode, err := d.getArrayNode(src)
1391		if err != nil {
1392			return errors.Wrapf(err, "failed to get array node")
1393		}
1394		if arrayNode == nil {
1395			return nil
1396		}
1397		iter := arrayNode.ArrayRange()
1398		sliceType := dst.Type()
1399		sliceValue := reflect.MakeSlice(sliceType, 0, iter.Len())
1400		elemType := sliceType.Elem()
1401	
1402		var foundErr error
1403		for iter.Next() {
1404			v := iter.Value()
1405			if elemType.Kind() == reflect.Ptr && v.Type() == ast.NullType {
1406				// set nil value to pointer
1407				sliceValue = reflect.Append(sliceValue, reflect.Zero(elemType))
1408				continue
1409			}
1410			dstValue, err := d.createDecodedNewValue(ctx, elemType, reflect.Value{}, v)
1411			if err != nil {
1412				if foundErr == nil {
1413					foundErr = err
1414				}
1415				continue
1416			}
1417			sliceValue = reflect.Append(sliceValue, d.castToAssignableValue(dstValue, elemType))
1418		}
1419		dst.Set(sliceValue)
1420		if foundErr != nil {
1421			return errors.Wrapf(foundErr, "failed to decode value")
1422		}
1423		return nil
1424	}
