1426	func (d *Decoder) decodeMapItem(ctx context.Context, dst *MapItem, src ast.Node) error {
1427		mapNode, err := d.getMapNode(src)
1428		if err != nil {
1429			return errors.Wrapf(err, "failed to get map node")
1430		}
1431		if mapNode == nil {
1432			return nil
1433		}
1434		mapIter := mapNode.MapRange()
1435		if !mapIter.Next() {
1436			return nil
1437		}
1438		key := mapIter.Key()
1439		value := mapIter.Value()
1440		if key.Type() == ast.MergeKeyType {
1441			if err := d.decodeMapItem(ctx, dst, value); err != nil {
1442				return errors.Wrapf(err, "failed to decode map with merge key")
1443			}
1444			return nil
1445		}
1446		*dst = MapItem{
1447			Key:   d.nodeToValue(key),
1448			Value: d.nodeToValue(value),
1449		}
1450		return nil
1451	}
