1453	func (d *Decoder) validateDuplicateKey(keyMap map[string]struct{}, key interface{}, keyNode ast.Node) error {
1454		k, ok := key.(string)
1455		if !ok {
1456			return nil
1457		}
1458		if d.disallowDuplicateKey {
1459			if _, exists := keyMap[k]; exists {
1460				return errDuplicateKey(fmt.Sprintf(`duplicate key "%s"`, k), keyNode.GetToken())
1461			}
1462		}
1463		keyMap[k] = struct{}{}
1464		return nil
1465	}
