1467	func (d *Decoder) decodeMapSlice(ctx context.Context, dst *MapSlice, src ast.Node) error {
1468		mapNode, err := d.getMapNode(src)
1469		if err != nil {
1470			return errors.Wrapf(err, "failed to get map node")
1471		}
1472		if mapNode == nil {
1473			return nil
1474		}
1475		mapSlice := MapSlice{}
1476		mapIter := mapNode.MapRange()
1477		keyMap := map[string]struct{}{}
1478		for mapIter.Next() {
1479			key := mapIter.Key()
1480			value := mapIter.Value()
1481			if key.Type() == ast.MergeKeyType {
1482				var m MapSlice
1483				if err := d.decodeMapSlice(ctx, &m, value); err != nil {
1484					return errors.Wrapf(err, "failed to decode map with merge key")
1485				}
1486				for _, v := range m {
1487					if err := d.validateDuplicateKey(keyMap, v.Key, value); err != nil {
1488						return errors.Wrapf(err, "invalid map key")
1489					}
1490					mapSlice = append(mapSlice, v)
1491				}
1492				continue
1493			}
1494			k := d.nodeToValue(key)
1495			if err := d.validateDuplicateKey(keyMap, k, key); err != nil {
1496				return errors.Wrapf(err, "invalid map key")
1497			}
1498			mapSlice = append(mapSlice, MapItem{
1499				Key:   k,
1500				Value: d.nodeToValue(value),
1501			})
1502		}
1503		*dst = mapSlice
1504		return nil
1505	}
