1507	func (d *Decoder) decodeMap(ctx context.Context, dst reflect.Value, src ast.Node) error {
1508		mapNode, err := d.getMapNode(src)
1509		if err != nil {
1510			return errors.Wrapf(err, "failed to get map node")
1511		}
1512		if mapNode == nil {
1513			return nil
1514		}
1515		mapType := dst.Type()
1516		mapValue := reflect.MakeMap(mapType)
1517		keyType := mapValue.Type().Key()
1518		valueType := mapValue.Type().Elem()
1519		mapIter := mapNode.MapRange()
1520		keyMap := map[string]struct{}{}
1521		var foundErr error
1522		for mapIter.Next() {
1523			key := mapIter.Key()
1524			value := mapIter.Value()
1525			if key.Type() == ast.MergeKeyType {
1526				if err := d.decodeMap(ctx, dst, value); err != nil {
1527					return errors.Wrapf(err, "failed to decode map with merge key")
1528				}
1529				iter := dst.MapRange()
1530				for iter.Next() {
1531					if err := d.validateDuplicateKey(keyMap, iter.Key(), value); err != nil {
1532						return errors.Wrapf(err, "invalid map key")
1533					}
1534					mapValue.SetMapIndex(iter.Key(), iter.Value())
1535				}
1536				continue
1537			}
1538	
1539			k := d.createDecodableValue(keyType)
1540			if d.canDecodeByUnmarshaler(k) {
1541				if err := d.decodeByUnmarshaler(ctx, k, key); err != nil {
1542					return errors.Wrapf(err, "failed to decode by unmarshaler")
1543				}
1544			} else {
1545				k = reflect.ValueOf(d.nodeToValue(key))
1546				if k.IsValid() && k.Type().ConvertibleTo(keyType) {
1547					k = k.Convert(keyType)
1548				}
1549			}
1550	
1551			if k.IsValid() {
1552				if err := d.validateDuplicateKey(keyMap, k.Interface(), key); err != nil {
1553					return errors.Wrapf(err, "invalid map key")
1554				}
1555			}
1556			if valueType.Kind() == reflect.Ptr && value.Type() == ast.NullType {
1557				// set nil value to pointer
1558				mapValue.SetMapIndex(k, reflect.Zero(valueType))
1559				continue
1560			}
1561			dstValue, err := d.createDecodedNewValue(ctx, valueType, reflect.Value{}, value)
1562			if err != nil {
1563				if foundErr == nil {
1564					foundErr = err
1565				}
1566			}
1567			if !k.IsValid() {
1568				// expect nil key
1569				mapValue.SetMapIndex(d.createDecodableValue(keyType), d.castToAssignableValue(dstValue, valueType))
1570				continue
1571			}
1572			mapValue.SetMapIndex(k, d.castToAssignableValue(dstValue, valueType))
1573		}
1574		dst.Set(mapValue)
1575		if foundErr != nil {
1576			return errors.Wrapf(foundErr, "failed to decode value")
1577		}
1578		return nil
1579	}
