1600	func (d *Decoder) readersUnderDir(dir string) ([]io.Reader, error) {
1601		pattern := fmt.Sprintf("%s/*", dir)
1602		matches, err := filepath.Glob(pattern)
1603		if err != nil {
1604			return nil, errors.Wrapf(err, "failed to get files by %s", pattern)
1605		}
1606		readers := []io.Reader{}
1607		for _, match := range matches {
1608			if !d.isYAMLFile(match) {
1609				continue
1610			}
1611			reader, err := d.fileToReader(match)
1612			if err != nil {
1613				return nil, errors.Wrapf(err, "failed to get reader")
1614			}
1615			readers = append(readers, reader)
1616		}
1617		return readers, nil
1618	}
1619	
1620	func (d *Decoder) readersUnderDirRecursive(dir string) ([]io.Reader, error) {
1621		readers := []io.Reader{}
1622		if err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
1623			if !d.isYAMLFile(path) {
1624				return nil
1625			}
1626			reader, err := d.fileToReader(path)
1627			if err != nil {
1628				return errors.Wrapf(err, "failed to get reader")
1629			}
1630			readers = append(readers, reader)
1631			return nil
1632		}); err != nil {
1633			return nil, errors.Wrapf(err, "interrupt walk in %s", dir)
1634		}
1635		return readers, nil
1636	}
