1638	func (d *Decoder) resolveReference() error {
1639		for _, opt := range d.opts {
1640			if err := opt(d); err != nil {
1641				return errors.Wrapf(err, "failed to exec option")
1642			}
1643		}
1644		for _, file := range d.referenceFiles {
1645			reader, err := d.fileToReader(file)
1646			if err != nil {
1647				return errors.Wrapf(err, "failed to get reader")
1648			}
1649			d.referenceReaders = append(d.referenceReaders, reader)
1650		}
1651		for _, dir := range d.referenceDirs {
1652			if !d.isRecursiveDir {
1653				readers, err := d.readersUnderDir(dir)
1654				if err != nil {
1655					return errors.Wrapf(err, "failed to get readers from under the %s", dir)
1656				}
1657				d.referenceReaders = append(d.referenceReaders, readers...)
1658			} else {
1659				readers, err := d.readersUnderDirRecursive(dir)
1660				if err != nil {
1661					return errors.Wrapf(err, "failed to get readers from under the %s", dir)
1662				}
1663				d.referenceReaders = append(d.referenceReaders, readers...)
1664			}
1665		}
1666		for _, reader := range d.referenceReaders {
1667			bytes, err := io.ReadAll(reader)
1668			if err != nil {
1669				return errors.Wrapf(err, "failed to read buffer")
1670			}
1671	
1672			// assign new anchor definition to anchorMap
1673			if _, err := d.parse(bytes); err != nil {
1674				return errors.Wrapf(err, "failed to decode")
1675			}
1676		}
1677		d.isResolvedReference = true
1678		return nil
1679	}
1680	
1681	func (d *Decoder) parse(bytes []byte) (*ast.File, error) {
1682		var parseMode parser.Mode
1683		if d.toCommentMap != nil {
1684			parseMode = parser.ParseComments
1685		}
1686		f, err := parser.ParseBytes(bytes, parseMode)
1687		if err != nil {
1688			return nil, errors.Wrapf(err, "failed to parse yaml")
1689		}
1690		normalizedFile := &ast.File{}
1691		for _, doc := range f.Docs {
1692			// try to decode ast.Node to value and map anchor value to anchorMap
1693			if v := d.nodeToValue(doc.Body); v != nil {
1694				normalizedFile.Docs = append(normalizedFile.Docs, doc)
1695			}
1696		}
1697		return normalizedFile, nil
1698	}
