1704	func (d *Decoder) decodeInit() error {
1705		if !d.isResolvedReference {
1706			if err := d.resolveReference(); err != nil {
1707				return errors.Wrapf(err, "failed to resolve reference")
1708			}
1709		}
1710		var buf bytes.Buffer
1711		if _, err := io.Copy(&buf, d.reader); err != nil {
1712			return errors.Wrapf(err, "failed to copy from reader")
1713		}
1714		file, err := d.parse(buf.Bytes())
1715		if err != nil {
1716			return errors.Wrapf(err, "failed to decode")
1717		}
1718		d.parsedFile = file
1719		return nil
1720	}
