1722	func (d *Decoder) decode(ctx context.Context, v reflect.Value) error {
1723		if len(d.parsedFile.Docs) <= d.streamIndex {
1724			return io.EOF
1725		}
1726		body := d.parsedFile.Docs[d.streamIndex].Body
1727		if body == nil {
1728			return nil
1729		}
1730		if err := d.decodeValue(ctx, v.Elem(), body); err != nil {
