package main

import (
	"fmt"
	"strings"

	yaml "github.com/goccy/go-yaml"
)

type Inner struct {
	Key string `yaml:"key"`
}
type Outer struct {
	First  string `yaml:"first"`
	Second Inner  `yaml:"second"`
}

func check(label, yml string) {
	v := Outer{Second: Inner{Key: "My default Value"}}
	if err := yaml.NewDecoder(strings.NewReader(yml)).Decode(&v); err != nil {
		fmt.Printf("FAIL [%s]: decode error: %s\n", label, err)
		return
	}
	if v.Second.Key != "My default Value" {
		fmt.Printf("FAIL [%s]: got %q, want \"My default Value\"\n", label, v.Second.Key)
	} else {
		fmt.Printf("PASS [%s]\n", label)
	}
}

func main() {
	check("null node",      "first: Test\nsecond:\n")
	check("comments only",  "first: Test\nsecond:\n  # just a comment\n")

	// Sanity: explicit field value must still win
	v2 := Outer{Second: Inner{Key: "My default Value"}}
	yaml.NewDecoder(strings.NewReader("first: Test\nsecond:\n  key: Overridden\n")).Decode(&v2)
	if v2.Second.Key == "Overridden" {
		fmt.Println("PASS [explicit override]")
	} else {
		fmt.Printf("FAIL [explicit override]: got %q\n", v2.Second.Key)
	}

	// Sanity: pointer field with null still goes to nil
	type OuterPtr struct {
		Field *Inner `yaml:"field"`
	}
	v3 := OuterPtr{Field: &Inner{Key: "default"}}
	yaml.NewDecoder(strings.NewReader("field: null\n")).Decode(&v3)
	if v3.Field == nil {
		fmt.Println("PASS [pointer null -> nil]")
	} else {
		fmt.Printf("FAIL [pointer null -> nil]: got %+v\n", v3.Field)
	}
}
EOF
go run /tmp/verify_fix.go 2>&1

